#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;
int cnt[26]={0};for(char c:s)++cnt[c-'a'];
priority_queue<tuple<int,int,char>>pq;
for(int i=0;i<26;++i)if(cnt[i])pq.push({cnt[i],-('a'+i),(char)('a'+i)});
string res;tuple<int,int,char> prev{0,0,0};
while(!pq.empty()){
auto cur=pq.top();pq.pop();
res+=get<2>(cur);
if(get<0>(prev)>0)pq.push(prev);
prev={get<0>(cur)-1,get<1>(cur),get<2>(cur)};}
if((int)res.size()!=(int)s.size())printf("\n");
else printf("%s\n",res.c_str());
return 0;}

